**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <cmath>
#include <iomanip>
using namespace std;

int main() {
    ifstream plik("wielokaty.txt");
    int k;
    plik >> k;
    double maxPole = -1, minPole = 1e18;
    int maxIdx = -1, minIdx = -1;
    cout << fixed << setprecision(2);
    for (int w = 0; w < k; w++) {
        int n;
        plik >> n;
        vector<int> X(n), Y(n);
        for (int i = 0; i < n; i++) plik >> X[i] >> Y[i];
        int sum2 = 0;
        for (int i = 0; i < n; i++) {
            int j = (i + 1) % n;
            sum2 += X[i] * Y[j] - X[j] * Y[i];
        }
        double pole = abs(sum2) / 2.0;
        cout << "Wielokat " << w + 1 << " (" << n << " wierzch.): pole = " << pole << endl;
        if (pole > maxPole) { maxPole = pole; maxIdx = w + 1; }
        if (pole < minPole) { minPole = pole; minIdx = w + 1; }
    }
    cout << "Najwieksze pole: wielokat " << maxIdx << ", pole = " << maxPole << endl;
    cout << "Najmniejsze pole: wielokat " << minIdx << ", pole = " << minPole << endl;
    return 0;
}
```

**Wyjasnienie**: Wzor sznurowadla (Shoelace formula) pozwala obliczyc pole dowolnego wielokata prostego ze wspolrzednych wierzcholkow. Sumujemy iloczyny x_i*y_{i+1} - x_{i+1}*y_i po wszystkich bokach (z zamknieciem), bierzemy wartosc bezwzgledna i dzielimy przez 2.

Weryfikacja:
- W1 (0,0)(6,0)(3,4): sum = (0*0-6*0) + (6*4-3*0) + (3*0-0*4) = 0+24+0 = 24. Pole = 24/2 = 12.00
- W2 (0,0)(10,0)(10,5)(0,5): sum = (0*0-10*0) + (10*5-10*0) + (10*5-0*5) + (0*0-0*5) = 0+50+50+0 = 100. Pole = 100/2 = 50.00
- W3 (0,0)(4,0)(6,3)(4,6)(0,4): sum = (0*0-4*0) + (4*3-6*0) + (6*6-4*3) + (4*4-0*6) + (0*0-0*4) = 0+12+24+16+0 = 52. Pole = 52/2 = 26.00
- W4 (0,0)(8,0)(4,3): sum = (0*0-8*0) + (8*3-4*0) + (4*0-0*3) = 0+24+0 = 24. Pole = 24/2 = 12.00
- Najwieksze: W2 (50.00), Najmniejsze: W1 (12.00) — przy remisie W1 i W4 program zwroci pierwszy napotkany.
